#!/usr/bin/env python3
"""Only immutable, intentional sources, never generated bytecode."""
import hashlib,json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
m=json.loads((root/'SOURCE_MANIFEST.json').read_text())
if m['root']!=root.name or m['version']!='v18.51b':raise RuntimeError('Source manifest root/version mismatch')
for rel,digest in m['files'].items():
    if '__pycache__' in rel or rel.endswith('.pyc'):raise RuntimeError('Compiled cache incorrectly listed as source')
    file=root/rel
    if not file.is_file() or hashlib.sha256(file.read_bytes()).hexdigest()!=digest:
        raise RuntimeError('Source drift: '+rel)
print('SOURCE IDENTITY VERIFIED',len(m['files']))
